state = {goal, messages, scratchpad, step: 0}
while not done(state) and state.step < MAX_STEPS and budget_ok(state):
    action = llm.decide(state, tools=allowed_tools(user))   # tool call or final answer
    if action.final: break
    if needs_approval(action): state = await human_approval(action)
    result = sandbox.run(action.tool, action.args, timeout=30)
    state.messages.append(observation(result))
    checkpoint(state)          # durable after every step
    state.step += 1
